  "content": "/* ---------------------------------------------------------------
   FemAI Cycle Tracker – style.css
   Accent colour: #336699
   Design system: 8px spacing, 8px border radius, CSS variables, light/dark
   --------------------------------------------------------------- */

:root {
  --accent: #336699;
  --spacing: 8px;
  --radius: 8px;
  --font-size: 14px;
  --bg-light: #f5f5f5;
  --bg-dark: #1e1e1e;
  --surface-light: #ffffff;
  --surface-dark: #2c2c2c;
  --text-light: #222222;
  --text-dark: #eeeeee;
  --border-light: #e0e0e0;
  --border-dark: #444444;
  --shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: var(--bg-dark);
    --surface: var(--surface-dark);
    --text: var(--text-dark);
    --border: var(--border-dark);
  }
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: var(--bg-light);
    --surface: var(--surface-light);
    --text: var(--text-light);
    --border: var(--border-light);
  }
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: var(--font-size);
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

/* -----------------------------------------------------------------
   Layout – sidebar, topbar, main content
   ----------------------------------------------------------------- */
#app {
  display: flex;
  min-height: 100vh;
  overflow: hidden;
}

/* Sidebar */
#sidebar {
  width: 240px;
  flex-shrink: 0;
  background: var(--accent);
  color: #ffffff;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease;
  z-index: 1000;
}

#sidebar.collapsed {
  transform: translateX(-100%);
}

.logo {
  padding: var(--spacing) calc(var(--spacing) * 2);
  font-weight: 600;
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  gap: var(--spacing);
}

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: var(--spacing);
  padding: var(--spacing) calc(var(--spacing) * 2);
  color: #ffffff;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.2s ease;
}

.nav-item:hover,
.nav-item.active {
  background: rgba(255, 255, 255, 0.15);
}

/* Sidebar toggle – visible only on small screens */
#sidebar-toggle {
  display: none;
  position: absolute;
  top: var(--spacing);
  right: -40px;
  width: 32px;
  height: 32px;
  background: #ffffff;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  box-shadow: var(--shadow);
}

#sidebar-toggle::before {
  content: "☰";
  font-size: 1rem;
  color: var(--accent);
}

/* Top bar */
#topbar {
  height: 56px;
  background: var(--surface);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 calc(var(--spacing) * 2);
  box-shadow: var(--shadow);
  position: sticky;
  top: 0;
  width: 100%;
  z-index: 500;
}

